import json

def transform(grid):
    """
    Rule:
    1. Find the background color (most frequent, typically 0)
    2. For each non-background color, find its max horizontal span across all rows
    3. For each row with a segment of color C:
       - If the leftmost segment of C has length == max_span[C], fill the ENTIRE row with 8
       - Otherwise, extend that segment to have length = max_span[C], centered
    4. Background cells stay background
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find max span for each color
    color_spans = {}

    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == 0:
                continue
            if val not in color_spans:
                color_spans[val] = []

            # Check if this is the start of a horizontal segment
            if c == 0 or row[c-1] != val:
                span_start = c
                while c < cols and row[c] == val:
                    c += 1
                span_len = c - span_start
                if span_len > 0:
                    color_spans[val].append(span_len)

    max_spans = {}
    for c, spans in color_spans.items():
        max_spans[c] = max(spans) if spans else 0

    # Apply transformation to each cell
    result = [[0] * cols for _ in range(rows)]

    for r, row in enumerate(grid):
        c = 0
        while c < cols:
            if row[c] == 0:
                result[r][c] = 0
                c += 1
            else:
                val = row[c]
                span_start = c
                while c < cols and row[c] == val:
                    c += 1
                span_len = c - span_start

                # Check if this segment's length equals max span for this color
                if span_len == max_spans[val]:
                    # Fill entire row with 8
                    result[r] = [8] * cols
                else:
                    # Extend/center segment to max_span length
                    if r < len(result):
                        for cc in range(span_start, min(span_start + max_spans[val], cols)):
                            if cc < cols:
                                # Center the segment if possible
                                # Find where to place the extended segment
                                if span_start >= max_spans[val]//2:
                                    start_pos = span_start - max_spans[val]//2
                                else:
                                    start_pos = span_start
                                start_pos = max(0, start_pos)
                                for pos in range(start_pos, min(start_pos + max_spans[val], span_start + span_len)):
                                    if pos < cols:
                                        result[r][pos] = val

    return result

