import json

def transform(grid):
    """
    Rule final hypothesis:
    - For each color C with max_span:
      - Rows with a segment of length == max_span: fill ENTIRE row with 8 (if max_span < width)
      - Rows with only shorter segments: extend EACH segment rightward to length = max_span
        (placing max_span cells starting at the first cell of the segment)
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find max span for each color
    color_spans = {}

    for r, row in enumerate(grid):
        for c in range(cols):
            val = row[c]
            if val == 0:
                continue
            if val not in color_spans:
                color_spans[val] = set()

            # Find all horizontal segments
            c_seg = c
            while c_seg < cols and row[c_seg] == val:
                if c_seg == 0 or row[c_seg-1] != val:
                    c_span_start = c_seg
                c_seg += 1
            c_span_len = c_seg - c_span_start
            color_spans[val].add(c_span_len)

    max_spans = {c: max(spans) for c, spans in color_spans.items()}

    # Apply transformation
    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        modified = False
        for c in range(cols):
            if result[r][c] != 0:
                val = result[r][c]

                # Find segment start and length
                seg_start = c
                while c < cols and grid[c] == val:
                    c += 1
                seg_len = c - seg_start

                # Check if any segment has length == max_span
                has_max_span_segment = seg_len == max_spans[val]

                if has_max_span_segment and max_spans[val] < cols:
                    # Fill entire row with 8
                    result[r] = [8] * cols
                    modified = True
                else:
                    # Extend THIS segment to max_span length
                    new_len = max_spans[val]

                    # Set first new_len cells to val
                    for cc in range(min(new_len, cols)):
                        if not modified:  # Only set once before filling with 8
                            result[r][cc] = val

        # If modified, we already set whole row, need to clear it for next color
        if modified:
            for c in range(cols):
                if result[r][c] != 0:  # Reset to grid values except what we set
                    result[r][c] = grid[r][c]  # This won't work... need rethink

    return result

