import json
from collections import defaultdict

def transform_v6_fixed(grid):
    rows = len(grid)
    cols = len(grid[0])
    width = cols

    # Find bounding box for each color
    color_rects = {}
    for val in range(1, 10):
        color_rects[val] = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                val = grid[r][c]
                if color_rects[val] is None:
                    color_rects[val] = (r, r, c, c)
                else:
                    color_rects[val] = (
                        min(color_rects[val][0], r),
                        max(color_rects[val][1], r),
                        min(color_rects[val][2], c),
                        max(color_rects[val][3], c)
                    )

    # Filter to only colors that exist
    valid_rects = {k: v for k, v in color_rects.items() if v is not None}

    # Max span for each color
    color_spans = {}
    for val in range(1, 10):
        max_len = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == val:
                    c_start = c
                    c2 = c
                    while c2 < cols and grid[r][c2] == val:
                        c2 += 1
                    seg_len = c2 - c_start
                    max_len = max(max_len, seg_len)
        color_spans[val] = max_len

    # Build output
    result = [[0] * cols for _ in range(rows)]

    for color, (min_r, max_r, min_c, max_c) in valid_rects.items():
        max_s = color_spans[color]

        for r in range(min_r, max_r + 1):
            has_full_segment = False
            has_any_color = False
            for c in range(cols):
                if grid[r][c] == color:
                    has_any_color = True
                    c_start = c
                    c2 = c
                    while c2 < cols and grid[r][c2] == color:
                        c2 += 1
                    seg_len = c2 - c_start
                    if seg_len == max_s and max_s < width:
                        has_full_segment = True
                        break

            if has_full_segment:
                result[r] = [8] * width
            elif has_any_color:
                for c in range(min_c, max_c + 1):
                    result[r][c] = color
            else:
                # Copy from highest row with color, within bounding box range
                for c in range(min_c, max_c + 1):
                    if grid[r-1][c] == color:
                        result[r][c] = color

    return result

