def transform(grid, background=5):
    """
    Transform each color by filling its bounding box with that color.
    Background color is 5.

    Rule: For each color, compute bounding box (min/max row, min/max col),
    fill all cells in bbox with that color. Original cells are copied first.
    """
    rows = len(grid)
    cols = len(grid[0])

