def bbox_fill(grid, background=0):
    """Fill each color's bounding box with that color."""
    rows = len(grid)
    cols = len(grid[0])

    # Convert to 0-based (background becomes 0)
    grid_inv = [[0 if c == background else c for c in row] for row in grid]

    # Find bounding box for each color
    color_rects = {}
    for r in range(rows):
        for c in range(cols):
            val = grid_inv[r][c]
            if val != 0 and val < 10:
                if val not in color_rects:
                    color_rects[val] = [r, r, c, c]
                else:
                    color_rects[val] = [
                        min(color_rects[val][0], r),
                        max(color_rects[val][1], r),
                        min(color_rects[val][2], c),
                        max(color_rects[val][3], c)
                    ]

    # Build output
    result = [[0] * cols for _ in range(rows)]

    # Copy original non-background
    for r in range(rows):
        for c in range(cols):
            val = grid_inv[r][c]
            if val != 0:
                result[r][c] = val

    # Fill each bbox
    for color in color_rects:
        min_r, max_r, min_c, max_c = color_rects[color]
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if result[r][c] == 0:
                    result[r][c] = color

    # Convert back (background=0)
    return [[c if c != 0 else background for c in row] for row in result]

